# Golden observations generated by the independent upstream Ruby implementation.
require 'json'
require File.join(ENV.fetch('VXLAN_RUBY', '/Users/wenwu.yan/Works/ruby/vxlan'), 'lib/vxlan/runtime_parser')
root = ENV.fetch('VXLAN_RUBY', '/Users/wenwu.yan/Works/ruby/vxlan')
spec = File.read(File.join(root, 'spec/runtime_parser_spec.rb'))
context = Object.new
context.define_singleton_method(:fixture) { |name| File.read(File.join(root, "spec/fixtures/netstack/#{name}.txt")) }
%w[bgp ospf cdp vpc].each do |name|
  body = spec.match(/  let\(:#{name}\) do\n(.*?)\n  end/m)[1]
  value = context.instance_eval(body)
  context.define_singleton_method(name) { value }
end
body = spec.match(/  let\(:outputs\) do\n(.*?)\n  end/m)[1]
context.instance_eval("def read_outputs\n#{body}\nend")
outputs = context.read_outputs
parser = Vxlan::RuntimeParser.new
cases = []
add = ->(id, name, text, complete=true) do
  result = parser.parse(name, text, complete: complete)
  cases << {id: id, name: name, text: text, complete: complete, expected: { status: result.status, records: result.records, issues: result.issues }}
end
outputs.each do |name, text|
  add.call("#{name}/valid", name, text)
  add.call("#{name}/incomplete", name, text, false)
  add.call("#{name}/unknown", name, text + "unrecognized firmware field\n")
  add.call("#{name}/empty", name, '')
  add.call("#{name}/unsupported", name, "% Invalid command at '^' marker.\n", false)
  add.call("#{name}/crlf", name, text.gsub("\n", "\r\n"))
  add.call("#{name}/duplicate", name, text * 2)
end
{nve_peers:'No peers found',nve_vnis:'No VNIs found',bgp_neighbors:'No BGP neighbors found',ospf_neighbors:'Total number of neighbors: 0',cdp_neighbors:'Total cdp entries displayed : 0',interfaces:'0 interfaces',port_channels:'Number of port-channels: 0',mac_addresses:'No entries found',l2route_macs:'No routes found',l2route_mac_ips:'Total number of routes: 0'}.each do |name, empty|
  add.call("#{name}/explicit_empty",name,empty)
  add.call("#{name}/contradictory_empty",name,outputs[name]+empty)
end
%w[--More--].concat(["-- More --", "hello\0world", "hello\e[31mworld", "hello\bworld", "SA\rFE"]).each_with_index { |s,i| add.call("terminal/#{i}",:interfaces,"Interface Status Description\nLo0 up #{s}\nLo1 up SAFE\n") }
add.call('terminal/split',:interfaces,"--\nMore\n--\n")
# Every line independently corrupted, removed, or duplicated tests boundaries and scoped state.
outputs.each do |name,text|
  text.lines.each_with_index do |line,i|
    lines=text.lines
    add.call("#{name}/remove_line_#{i+1}",name,(lines[0...i]+lines[i+1..]).join)
    add.call("#{name}/repeat_line_#{i+1}",name,(lines[0..i]+[line]+lines[i+1..]).join)
    add.call("#{name}/corrupt_line_#{i+1}",name,(lines[0...i]+["unrecognized firmware field\n"]+lines[i+1..]).join)
  end
end
bgp=context.bgp;ospf=context.ospf;cdp=context.cdp;vpc=context.vpc
add.call('bgp/scopes',:bgp_neighbors,bgp+bgp.sub('VRF default','VRF BLUE'))
add.call('bgp/empty_scope',:bgp_neighbors,bgp+"BGP summary information for VRF GREEN, address family L2VPN EVPN\nNo BGP neighbors found\n")
['300.0.2.2','2001:DB8::2'].each { |ip| add.call("bgp/ip/#{ip}",:bgp_neighbors,bgp.gsub('192.0.2.2',ip)) }
[['Type-12','Type-99'],['I 65002 12','I 65002 13'],['I 65002','Z 65002'],['5 4 0 3 0','5 4 0 3'],['5 4 0 3 0','9 9 0 0 0'],['State/PfxRcd',"State/\nPfxRcd"],['65001','1.2'],['65001','65536.2'],['192.0.2.1','2001:db8::1']].each_with_index { |(a,b),i| add.call("bgp/mutate/#{i}",:bgp_neighbors,bgp.gsub(a,b)) }
%w[0 Idle Active Connect OpenSent OpenConfirm Shutdown].concat(['Idle (Admin)','invalid']).each { |state| add.call("bgp/state/#{state}",:bgp_neighbors,bgp.lines.take(5).join.sub('1d 12',"1d #{state}")) }
add.call('bgp/conflicting_identity',:bgp_neighbors,bgp+bgp.sub('65001','65003'))
add.call('bgp/equivalent_identity',:bgp_neighbors,bgp+bgp.sub('65001','0.65001').sub('192.0.2.2','192.0.2.3'))
add.call('ospf/scopes',:ospf_neighbors,ospf+ospf.sub('UNDERLAY VRF default','TENANT VRF BLUE'))
add.call('ospf/wrong_scopes',:ospf_neighbors,ospf.sub('neighbors: 1','neighbors: 0')+ospf.sub('UNDERLAY VRF default','TENANT VRF BLUE').sub('neighbors: 1','neighbors: 2'))
add.call('ospf/empty_scope',:ospf_neighbors,ospf+"OSPF Process ID EMPTY VRF GREEN\nTotal number of neighbors: 0\n")
['256 FULL','1 INVALID','1 DOWN','1 2WAY'].each { |s| add.call("ospf/state/#{s}",:ospf_neighbors,ospf.sub('1 FULL',s)) }
wrapped=outputs[:nve_peers].sub('Router-Mac',"Route\nr-Mac").sub('0011.2233.4455',"0011.\n2233.4455")
add.call('nve/wrapped',:nve_peers,wrapped)
add.call('nve/broken_wrap',:nve_peers,wrapped.sub('2233.4455','2233.445'))
add.call('nve/no_mac',:nve_peers,outputs[:nve_peers].sub('0011.2233.4455','n/a'))
add.call('nve/invalid_ip',:nve_peers,outputs[:nve_peers].sub('192.0.2.2','300.0.2.2'))
%w[UNKNOWN SA S-ND SU Xconn MS-IR HYB].each { |s| add.call("vni/flags/#{s}",:nve_vnis,outputs[:nve_vnis].sub(' SA'," #{s}")) }
%w[0 16777215 16777216].each { |s| add.call("vni/id/#{s}",:nve_vnis,outputs[:nve_vnis].sub('10110',s)) }
%w[224.0.0.1 239.255.255.255 192.0.2.1 n/a unicastbgp].each { |s| add.call("vni/group/#{s}",:nve_vnis,outputs[:nve_vnis].sub('UnicastBGP',s)) }
add.call('vni/legends',:nve_vnis,"Codes: CP - Control Plane        DP - Data Plane\nUC - Unconfigured      SA - Suppress ARP\nS-ND - Suppress ND\n"+outputs[:nve_vnis])
interfaces=<<~TEXT
Port VRF Status IP Address Speed MTU
mgmt0 management up 192.0.2.1 1000 1500
Ethernet VLAN Type Mode Status Reason Speed Port
Interface Ch #
Eth1/1 -- eth routed down XCVR not inserted auto(D) --
Port-channel VLAN Type Mode Status Reason Speed Protocol
Po101 40 eth trunk up none 25G(D) LACP
Interface Status Description
Lo0 up backup down interface
Interface Secondary VLAN(Type) Status Reason
Vlan40 -- down Administratively down
Port Status Reason MTU
nve1 up none 9216
Port Name Status Vlan Duplex Speed Type
Eth1/2 backup up link down routed full 10G 10Gbase-SR
TEXT
add.call('interfaces/layouts',:interfaces,interfaces)
add.call('interfaces/mtu',:interfaces,interfaces.sub('1000 1500','1000 broken'))
add.call('interfaces/header',:interfaces,interfaces.sub('Status IP Address','Status Unknown'))
header="Group Port- Type Protocol Member Ports\n"
["10 Po10(SU) Eth LACP Eth1/1(P) Eth1/1(D) Eth1/2(P)\n","10 Po10(SU) Eth LACP Eth1/1(P) Eth1/2(P)\n  Ethernet1/1(D)\n","10 Po10(SU) Eth LACP Eth1/1(P) Eth1/2(P)\n20 Po20(SU) Eth LACP Ethernet1/1(P) Eth1/3(P)\n"].each_with_index { |text,i| add.call("port/conflict/#{i}",:port_channels,header+text) }
["broken row\n",header,"Number of port-channels: 1\n","Eth1/3(P) malformed\n"].each_with_index { |text,i| add.call("port/boundary/#{i}",:port_channels,header+"10 Po10(SU) Eth LACP Eth1/1(P)\n"+text+"  Eth1/2(P)\n") }
add.call('port/wrapped_empty',:port_channels,header+"Channel\n100 Po100(SD) Eth NONE --\n101 Po101(SU) Eth LACP Eth1/1(P)\n  Eth1/2(P)\n")
mac="VLAN MAC Address Type age Secure NTFY Ports\nG - 0011.2233.4455 static - F F sup-eth1(R)\nG - 0011.2233.4455 static - F F Lo0(R) (Lo0)\n* 999 aabb.ccdd.eeff static - F F Vlan999\nG 999 aabb.ccdd.eeff static - F F sup-eth1(R)\n"
add.call('mac/gateway',:mac_addresses,mac)
add.call('mac/gateway_duplicate',:mac_addresses,mac+mac.lines.last)
add.call('mac/unmarked',:mac_addresses,mac.gsub('G -','* -'))
add.call('mac/dynamic',:mac_addresses,mac.gsub('static','dynamic'))
add.call('mac/unicode',:mac_addresses,"(NA)- Not Applicable A – ESI Active Path, S – ESI Standby Path\n"+outputs[:mac_addresses])
[['id : 7','id : unknown'],['configured : 1','configured : 2'],['configured : 1','configured : broken'],['up success  success','down* Not  Consistency Check Not']].each_with_index { |(a,b),i| add.call("vpc/mutate/#{i}",:vpc,vpc.sub(a,b)) }
add.call('vpc/wrapped',:vpc,vpc.sub('up success  success','down* Not  Consistency Check Not')+"Applicable  Performed\n")
add.call('vpc/truncated',:vpc,vpc.gsub('110,120','110,...')+"130,140\n")
add.call('cdp/metadata',:cdp_neighbors,cdp.sub('Total cdp entries',"Physical Location: `\nLocal Interface MAC: 00:11:22:33:44:55\nRemote Interface MAC: AA:BB:CC:DD:EE:FF\nDC_UUID: EXAMPLE1234\nTotal cdp entries"))
add.call('cdp/uuid_null',:cdp_neighbors,cdp+"DC_UUID:\n")
['System Name: OTHER','Interface: Ethernet1/3, Port ID (outgoing port): Ethernet1/2','MTU: 1500','Platform: N7K, Capabilities: Router Switch','Holdtime: 100 sec'].each_with_index { |s,i| add.call("cdp/conflict/#{i}",:cdp_neighbors,cdp+s+"\n"+s+"\n") }
add.call('cdp/fallback',:cdp_neighbors,cdp.lines.reject { |l| l.start_with?('System Name:') }.join)
add.call('cdp/separator',:cdp_neighbors,cdp.sub('Second software line',"--------\nunknown field"))
add.call('l2/legacy',:l2route_mac_ips,"Topology ID Mac Address Prod Host IP Next Hop (s)\n8 0011.2233.4455 HMM 192.0.2.11 Local\n")
add.call('l2/ifindex',:l2route_macs,"Topology Mac Address Prod Next Hop (s)\n8 0011.2233.4455 Local Ifindex   4362086\n")
[['192.0.2.11 ','300.0.2.11 '],['192.0.2.11 ','192.0.2.0/24 '],['(Label: 100008)','(Label:'],['(Label: 100008)','(Label: 4294967296)'],['BGP    --            0','BGP    --            broken'],['(Label: 100008)','(Label: 100008),']].each_with_index { |(a,b),i| add.call("l2/invalid/#{i}",:l2route_mac_ips,outputs[:l2route_mac_ips].sub(a,b)) }
add.call('l2/duplicate_hop',:l2route_macs,outputs[:l2route_macs].sub('192.0.2.22','192.0.2.21'))
# Adversarial scalar and boundary cases exercise behavior beyond recorded specs.
%w[9223372036854775808 18446744073709551616 00000000000000000000000000001].each do |number|
  add.call("numeric/bgp/#{number}",:bgp_neighbors,bgp.gsub('10 20 123',"#{number} 20 123"))
  add.call("numeric/ospf/#{number}",:ospf_neighbors,ospf.sub('neighbors: 1',"neighbors: #{number}"))
  add.call("numeric/port/#{number}",:port_channels,"Number of port-channels: #{number}\n")
  add.call("numeric/cdp/#{number}",:cdp_neighbors,cdp.sub('displayed : 1',"displayed : #{number}"))
  add.call("numeric/vpc/#{number}",:vpc,vpc.sub('configured : 1',"configured : #{number}"))
  add.call("numeric/route/#{number}",:l2route_macs,"Total number of routes: #{number}\n")
end
%w[[2001:db8::1] [192.0.2.1] fe80::1%eth0 fe80::1%a-b fe80::1%a.b fe80::1%a:b fe80::1%ab_c ::192.0.2.1 ::ffff:c000:201 ::ffff:0:192.0.2.1 ::1:0 ::2].each do |ip|
  add.call("address/cdp/#{ip}",:cdp_neighbors,cdp.sub('192.0.2.2',ip))
  add.call("address/interface/#{ip}",:interfaces,"Port VRF Status IP Address\nmgmt0 management up #{ip}\n")
  add.call("address/route/#{ip}",:l2route_mac_ips,"Topology Mac Address Host IP Prod Next-Hops\n8 0011.2233.4455 #{ip} BGP Local\n")
end
["\u00a0","\u2028","\u3000"].each_with_index do |space,i|
  add.call("unicode/leading/#{i}",:interfaces,"#{space}Interface Status Description\nLo0 up safe\n")
  add.call("unicode/words/#{i}",:interfaces,"Interface Status Description\nLo0#{space}up safe\n")
  add.call("unicode/trailing/#{i}",:interfaces,"Interface Status Description\nLo0 up safe#{space}\n")
end
(0..31).to_a.concat([127]).each { |byte| add.call("terminal/byte/#{byte}",:interfaces,"Interface Status Description\nLo0 up A#{byte.chr}B\n") }
["\n","\n\n"," \n  \n", "\t", " "].each_with_index do |space,i|
  add.call("scope/bgp/#{i}",:bgp_neighbors,bgp+space+bgp.sub('VRF default','VRF BLUE'))
  add.call("scope/ospf/#{i}",:ospf_neighbors,ospf+space+ospf.sub('UNDERLAY VRF default','TENANT VRF BLUE').sub('192.0.2.2','300.0.2.2'))
end
add.call('l2/compact_hop_header',:l2route_mac_ips,"Topology ID Mac Address Prod Host IP Next Hop(s)\n8 0011.2233.4455 HMM 192.0.2.11 Local\n")
%w[Local Ifindex nve1 Lo0 Vlan10 vPC10 Po10 port-channel10 Ethernet1/1].each do |hop|
 add.call("l2/hop/#{hop}",:l2route_macs,"Topology Mac Address Prod Next-Hops\n8 0011.2233.4455 BGP #{hop}\n")
end
File.write(File.join(__dir__,'golden.json'),JSON.pretty_generate(cases)+"\n")
puts "generated #{cases.size} independent Ruby observations"
